using Microsoft.EntityFrameworkCore;
public sealed class EComDbContext:DbContext
{
 public EComDbContext(DbContextOptions<EComDbContext> options):base(options){Database.AutoTransactionBehavior=AutoTransactionBehavior.Never;}
 public DbSet<User> Users=>Set<User>();public DbSet<Category> Categories=>Set<Category>();public DbSet<Product> Products=>Set<Product>();public DbSet<ProductImage> ProductImages=>Set<ProductImage>();public DbSet<Address> Addresses=>Set<Address>();public DbSet<Cart> Carts=>Set<Cart>();public DbSet<CartItem> CartItems=>Set<CartItem>();public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderItem> OrderItems=>Set<OrderItem>();public DbSet<Payment> Payments=>Set<Payment>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();
 protected override void OnModelCreating(ModelBuilder m){base.OnModelCreating(m);m.Entity<User>().ToCollection("users");m.Entity<Category>().ToCollection("categories");m.Entity<Product>().ToCollection("products");m.Entity<ProductImage>().ToCollection("product_images");m.Entity<Address>().ToCollection("addresses");m.Entity<Cart>().ToCollection("carts");m.Entity<CartItem>().ToCollection("cart_items");m.Entity<Order>().ToCollection("orders");m.Entity<OrderItem>().ToCollection("order_items");m.Entity<Payment>().ToCollection("payments");m.Entity<AuditLog>().ToCollection("audit_logs");m.Entity<User>().HasIndex(x=>x.Email).IsUnique();m.Entity<Category>().HasIndex(x=>x.Slug).IsUnique();m.Entity<Product>().HasIndex(x=>x.Sku).IsUnique();m.Entity<Product>().HasIndex(x=>new{x.CategoryId,x.IsActive});m.Entity<Cart>().HasIndex(x=>x.UserId).IsUnique();m.Entity<CartItem>().HasIndex(x=>new{x.CartId,x.ProductId}).IsUnique();m.Entity<Order>().HasIndex(x=>x.OrderNumber).IsUnique();m.Entity<Payment>().HasIndex(x=>x.TransactionId);m.Entity<Product>().Ignore(x=>x.Category).Ignore(x=>x.Images);m.Entity<Category>().Ignore(x=>x.Products);m.Entity<ProductImage>().Ignore(x=>x.Product);m.Entity<Cart>().Ignore(x=>x.Items);m.Entity<CartItem>().Ignore(x=>x.Cart).Ignore(x=>x.Product);m.Entity<Order>().Ignore(x=>x.Items).Ignore(x=>x.ShippingAddress);m.Entity<OrderItem>().Ignore(x=>x.Order);}
 public override int SaveChanges(){AssignIds();return base.SaveChanges();}public override Task<int> SaveChangesAsync(CancellationToken ct=new()){AssignIds();return base.SaveChangesAsync(ct);}void AssignIds(){foreach(var e in ChangeTracker.Entries().Where(e=>e.State==EntityState.Added)){var p=e.Properties.FirstOrDefault(x=>x.Metadata.Name=="Id");if(p is not null&&p.CurrentValue is long id&&id==0)p.CurrentValue=MongoId.Next();}}
}
internal static class MongoId{static long _value=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()*1000;public static long Next()=>Interlocked.Increment(ref _value);}
public sealed class User { public long Id{get;set;} public string Name{get;set;}="";public string Email{get;set;}="";public string PasswordHash{get;set;}="";public string Role{get;set;}="CUSTOMER";public bool IsActive{get;set;}=true;public DateTimeOffset CreatedAt{get;set;}=DateTimeOffset.UtcNow; }
public sealed class Category { public long Id{get;set;}public string Name{get;set;}="";public string Slug{get;set;}="";public string? Description{get;set;}public string? ImageUrl{get;set;}public bool IsActive{get;set;}=true;public int DisplayOrder{get;set;}public DateTimeOffset CreatedAt{get;set;}=DateTimeOffset.UtcNow;public ICollection<Product> Products{get;set;}=[]; }
public sealed class Product { public long Id{get;set;}public long CategoryId{get;set;}public string Name{get;set;}="";public string Sku{get;set;}="";public string? Description{get;set;}public decimal Price{get;set;}public decimal? CompareAtPrice{get;set;}public int StockQuantity{get;set;}public bool IsActive{get;set;}=true;public bool IsDeleted{get;set;}public DateTimeOffset CreatedAt{get;set;}=DateTimeOffset.UtcNow;public DateTimeOffset UpdatedAt{get;set;}=DateTimeOffset.UtcNow;public Category Category{get;set;}=null!;public ICollection<ProductImage> Images{get;set;}=[]; }
public sealed class ProductImage { public long Id{get;set;}public long ProductId{get;set;}public string Url{get;set;}="";public bool IsPrimary{get;set;}public int DisplayOrder{get;set;}public Product Product{get;set;}=null!; }
